from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, Output
from lfx.schema.data import Data


class FirecrawlResultsToDataList(Component):
    display_name = "Firecrawl → Data List"
    inputs = [DataInput(name="crawl_data", display_name="Crawl Data")]
    outputs = [Output(display_name="Data List", name="data_list", method="convert")]

    def convert(self) -> list[Data]:
        raw = self.crawl_data.data.get("results", {})
        pages = raw.get("data", [])
        return [
            Data(
                text=page.get("markdown", ""),
                data={
                    "source_url": page.get("metadata", {}).get("source_url", ""),
                    "title": page.get("metadata", {}).get("title", ""),
                },
            )
            for page in pages
        ]

